    ) values (
        p_user_id, p_task_date, p_mode,
        p_active_app_count, p_carry_in,
        p_carry_in, 0, 0,
        true, true, true, v_known_streak, 0, clock_timestamp(),
        null, null,
        1, 0, p_carry_in, p_carry_out,
        null, p_task_date
    )
